ALTER TABLE "t_tutors" ALTER COLUMN "annotations" SET DEFAULT '{"mode":"required","ai":[{"key":"isCorrect","scale":"yes-no","question":"Was der Tutor schreibt, ist nicht ganz richtig.","tooltip":"Wählen Sie diese Option, wenn die Aussage falsche, ungenaue, verzerrte oder unvollständige Anteile enthält. Fiktive Szenarien, die der Tutor für Fallbeispiele generiert, können ignoriert werden."}],"user":[{"key":"thoughtAboutIndex","scale":"0-10","question":"Wie aktiv haben Sie nachgedacht (0 = gar nicht, 10 = sehr aktiv)?","tooltip":"Aktives Nachdenken bedeutet, dass Sie sich bewusst mit dem Inhalt auseinandergesetzt haben – etwa indem Sie sich selbst Fragen gestellt, kritisch reflektiert, das Thema mit bereits Gelerntem verknüpft oder an konkrete Beispiele und Praxissituationen gedacht haben. Aktives Nachdenken zahlt sich aus – es verbessert nicht nur Ihr Verständnis, sondern auch Ihren Lernerfolg."}]}'::json;